-- Migration: Seed French Learning Resources Template and Extend Signup Trigger

CREATE TABLE IF NOT EXISTS public.learning_resources_seed_template (
  id                 uuid primary key default gen_random_uuid(),
  title              text not null,
  url                text,
  resource_type      text not null,
  section            text not null,
  level              text,
  skills             text,
  notes              text,
  recommended        boolean not null default false,
  her_favorite       boolean not null default false,
  source_attribution text
);

TRUNCATE TABLE public.learning_resources_seed_template;


-- Extend handle_new_user() trigger function to auto-seed learning_resources on signup
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER SET search_path = ''
AS $$
BEGIN
  -- 1. Create user profile
  VALUES (
    new.id,
    COALESCE(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name'),
    new.raw_user_meta_data->>'avatar_url'
  )
  ON CONFLICT (id) DO NOTHING;

  -- 2. Auto-seed 251 curated French learning resources for new user
    user_id, title, url, resource_type, section, level, skills, notes, recommended, her_favorite, source_attribution
  )
  SELECT
    new.id, title, url, resource_type, section, level, skills, notes, recommended, her_favorite, source_attribution
  FROM public.learning_resources_seed_template;

  RETURN new;
END;
$$;

-- Seed resources for existing users if not already populated
SELECT u.id, t.title, t.url, t.resource_type, t.section, t.level, t.skills, t.notes, t.recommended, t.her_favorite, t.source_attribution
FROM auth.users u
CROSS JOIN public.learning_resources_seed_template t
WHERE NOT EXISTS (
  SELECT 1 FROM public.learning_resources lr WHERE lr.user_id = u.id
);
