INSERT INTO public.learning_resources_seed_template (title, url, resource_type, section, level, skills, notes, recommended, her_favorite, source_attribution) VALUES
('Anki', NULL, 'app', 'core_course', 'all', 'Reading, Listening', 'Flashcards app with audio support. Either download a pre-made French set or make your own as you go - utilizes a spaced repetition algorithm to help memorization', false, false, 'tsannifer''s French resources spreadsheet'),
('Apprendre le Français avec TV5Monde', 'http://apprendre.tv5monde.com/en', 'website', 'core_course', 'all', 'Listening', 'Short videos accompanied by listening comprehension questions. Also sorts exercises by level (A1 through B2) and offers a "Test de Connaissance du Français" / TCF', true, false, 'tsannifer''s French resources spreadsheet'),
('Clozemaster', 'https://www.clozemaster.com', 'website', 'core_course', 'all', 'Reading, Writing', 'Gamified learning through "mass exposure to vocabulary in context."', false, false, 'tsannifer''s French resources spreadsheet'),
('Coffee Break French', 'http://www.coffeebreakfrench.com/', 'podcast', 'core_course', 'all', 'Listening', 'Shortened episodes are free, full versions are paid. Covers scripted convos and explains vocab/grammar concepts.', false, false, 'tsannifer''s French resources spreadsheet'),
('Conjugaison française', 'http://commentconjuguer.com/', 'browser_extension', 'core_course', 'all', 'Reading, Writing', 'Chrome extension to easily search verb conjugations (entirely in French)', false, false, 'tsannifer''s French resources spreadsheet'),
('Fabulang', 'https://www.fabulang.com/', 'website', 'core_course', 'all', 'Reading', 'Alpha website for reading practice', false, false, 'tsannifer''s French resources spreadsheet'),
('Forvo', 'https://forvo.com/languages/fr/', 'website', 'core_course', 'all', 'Listening, Speaking', 'Has a library of audio clips by native Francophones, pronouncing common words & phrases', false, false, 'tsannifer''s French resources spreadsheet'),
('Français Facile', 'https://www.francaisfacile.com', 'website', 'core_course', 'all', 'Self-Assessment', 'Self-assessment tests. There is an English version of the site (www.tolearnfrench.com)', false, false, 'tsannifer''s French resources spreadsheet'),
('France Bienvenue', 'https://francebienvenue1.wordpress.com/', 'website', 'core_course', 'all', 'Listening', 'A blog with regular updates of short conversation recordings + transcripts for French learners (everything is in French)', false, false, 'tsannifer''s French resources spreadsheet'),
('French Proficiency Test', 'http://www.transparent.com/learn-french/proficiency-test.html', 'website', 'core_course', 'all', 'Self-Assessment', 'A mock proficiency test that includes grammar, vocabulary, and reading comprehension', true, false, 'tsannifer''s French resources spreadsheet'),
('French Sounds', 'https://www.youtube.com/channel/UC2L9w7ozDeUl1w5ZjUPCOQA', 'youtube', 'core_course', 'all', 'Listening, Speaking', 'YouTube channel that focuses on teaching French pronunciation/sounds. I recommend taking a look at the nasal vowels.', true, false, 'tsannifer''s French resources spreadsheet'),
('FrenchPod101 (PODCASTS)', 'https://www.frenchpod101.com/', 'podcast', 'core_course', 'all', 'Listening, Speaking', 'French & English podcast for all levels', false, false, 'tsannifer''s French resources spreadsheet'),
('HelloTalk', 'https://www.hellotalk.com/', 'app', 'core_course', 'all', 'Language Exchange / Listening, Speaking, Reading, Writing', 'Connect to speakers of your target language. You can exchange and correct text messages, send audio clips, and make live calls. Live video calls are premium (but Tandem allows them for free)', true, false, 'tsannifer''s French resources spreadsheet'),
('Interpals', 'https://www.interpals.net', 'website', 'core_course', 'all', 'Language Exchange / Listening, Speaking, Reading, Writing', '(never used it) - a web site / social media site that allows people to search for and connect with language exchange penpals.', false, false, 'tsannifer''s French resources spreadsheet'),
('Language Guide - French', 'http://www.languageguide.org/french/', 'website', 'core_course', 'all', 'Reading, Writing, Listening', 'Includes audio clips to help with pronunciation, grammar concepts, reading/listening, etc.', false, false, 'tsannifer''s French resources spreadsheet'),
('Language Reactor', 'https://chrome.google.com/webstore/detail/language-reactor/hoombieeljmmljlkjmnheibnpciblicm', 'browser_extension', 'core_course', 'all', 'Reading, Listening', 'A language learning extension that uses dual subtitles on Netflix, YouTube, etc.', false, false, 'tsannifer''s French resources spreadsheet'),
('Librivox', 'https://www.librivox.org', 'audiobook', 'core_course', 'all', 'Listening', 'A resource for free audiobooks, with many available in French.', false, false, 'tsannifer''s French resources spreadsheet'),
('Ling', NULL, 'app', 'core_course', 'all', 'Reading, Writing, Listening', 'App that mainly focuses on Asian and Eastern European languages but has a ton of options and has native speakers for audio recordings', false, false, 'tsannifer''s French resources spreadsheet'),
('Lingvist', 'https://www.lingvist.com', 'app', 'core_course', 'all', 'Reading, Writing, Listening', 'Fill-in-the-blank vocab learning, lots of texts for reading comp, audio recordings with transcripts for listening, and pronunciation/grammar guides', true, false, 'tsannifer''s French resources spreadsheet'),
('Litterature audio (in conjunction with Wikisource)', 'http://www.litteratureaudio.com/', 'website', 'core_course', 'all', 'Listening', '6000+ free French audiobooks (website is entirely in French)', false, false, 'tsannifer''s French resources spreadsheet'),
('Memrise', 'https://www.memrise.com', 'app', 'core_course', 'all', 'Reading, Writing, Listening', 'Vocab/expression builder. Of all the gamified learning apps, Memrise has the best [non-robotic] audio clips + vids of native speakers.', true, false, 'tsannifer''s French resources spreadsheet'),
('Readlang', 'http://readlang.com/', 'browser_extension', 'core_course', 'all', 'Reading', 'Extension that allows you to translate words on web pages and then review via flashcards.', false, false, 'tsannifer''s French resources spreadsheet'),
('Quizlet', 'https://quizlet.com/', 'app', 'core_course', 'all', 'Reading, Writing', 'Flashcards site/app - you can search for other user-created decks or make your own', false, false, 'tsannifer''s French resources spreadsheet'),
('Speechling', 'https://speechling.com/', 'website', 'core_course', 'all', 'Listening, Speaking', 'Listen to native speakers speak, imitate them and record yourself, and receive feedback on your accent.', false, false, 'tsannifer''s French resources spreadsheet'),
('Tandem', NULL, 'app', 'core_course', 'all', 'Language Exchange / Listening, Speaking, Reading, Writing', 'Connect to speakers of your target language. You can exchange and correct text messages, send audio clips, and make live calls. Supports video calls for free.', true, false, 'tsannifer''s French resources spreadsheet'),
('Wikisource (in conjunction with Litterature audio)', 'https://fr.wikisource.org/wiki/Wikisource:Accueil', 'website', 'core_course', 'all', 'Reading', 'A wiki full of free French texts. You can pair it with "Litterature audio" to develop some mix of reading/listening comprehension, as well as pronunciation practice (by mimicking the native speakers'' pronunciations)', false, false, 'tsannifer''s French resources spreadsheet'),
('Wordreference', 'http://www.wordreference.com/enfr/', 'website', 'core_course', 'all', 'Reading, Writing', 'A dictionary that allows you to look up common expressions from EN-FR / vice versa.', false, false, 'tsannifer''s French resources spreadsheet'),
('155 Minutes to Learn French with Vincent # Unit 1', 'https://www.youtube.com/watch?v=kSrHmDBTDvQ', 'youtube', 'core_course', 'absolute_beginner', 'Reading, Listening, Speaking', 'Vincent speaks clearly and this is his first unit of lessons. He has over 100,000 videos on many different grammar/vocab concepts', false, false, 'tsannifer''s French resources spreadsheet'),
('Busuu', 'https://www.busuu.com', 'app', 'core_course', 'absolute_beginner', 'Reading, Writing', 'Flashcards & small quizzes. You can also write sentences and have native speakers correct you.', false, false, 'tsannifer''s French resources spreadsheet'),
('Duolingo', 'https://www.duolingo.com', 'app', 'core_course', 'absolute_beginner', 'Reading, Writing, Listening, Speaking', '(2021 update) Moved this to [ABSOLUTE BEGINNER] because there have been great improvements for brand-new learners over the years', true, false, 'tsannifer''s French resources spreadsheet'),
('Drops', 'https://languagedrops.com/', 'app', 'core_course', 'absolute_beginner', 'Reading, Writing', 'Visual-based language learning app', false, false, 'tsannifer''s French resources spreadsheet'),
('Language Transfer: Introduction to French', 'https://www.youtube.com/watch?v=LsG_0hyr_ro&list=PLeA5t3dWTWvvZln1pJ-Ij8xOmS_3zH-4j', 'youtube', 'core_course', 'absolute_beginner', 'Speaking, Listening', 'From the creator of the AWESOME "Complete Greek" Language Transfer series. Great audio course that''s 100% free.', true, false, 'tsannifer''s French resources spreadsheet'),
('Lawless French', 'https://www.lawlessfrench.com/', 'website', 'core_course', 'absolute_beginner', 'Reading, Writing, Listening, Speaking', 'Beginners should check out the pronunciation guide on the website. Also has a lot of exercises/activities for every level.', false, false, 'tsannifer''s French resources spreadsheet'),
('Learn French Pronunciation', 'https://www.youtube.com/playlist?list=PLtJL6GKh6j0W3tMIoHyYC0Q3hfGBb9Zdu', 'youtube', 'core_course', 'absolute_beginner', 'Listening, Speaking', 'The vids are in reverse order. Watch the last/4th video first, then 3rd, 2nd, and 1st. Covers pronunciation tips & common mistakes to avoid.', false, false, 'tsannifer''s French resources spreadsheet'),
('Learn French with Alexa (Lessons 1-20)', 'https://www.youtube.com/playlist?list=PLV1-QgpUU7N3ZGbRMIrV24FCuvZoMt4xw', 'youtube', 'core_course', 'absolute_beginner', 'Reading, Listening, Speaking', 'A nice way to ease into French with a semi-interactive (pausing once in a while to wait for you to repeat answers) instructor', true, false, 'tsannifer''s French resources spreadsheet'),
('Memrise (French 1)', NULL, 'app', 'core_course', 'absolute_beginner', 'Reading, Writing, Listening', 'IMO better way to start than Duolingo for absolute beginners. Otherwise, go with Duolingo first and skip to higher Memrise levels.', true, false, 'tsannifer''s French resources spreadsheet'),
('Polly Lingual', 'https://pollylingu.al/fr/en/courses/1', 'website', 'core_course', 'absolute_beginner', 'Reading, Writing, Listening', '"Freemium" - more beginner lessons available for free than advanced. Never used it but the audio tracks sound pretty clear.', false, false, 'tsannifer''s French resources spreadsheet'),
('Wikibooks: French', 'https://en.wikibooks.org/wiki/French', 'website', 'core_course', 'absolute_beginner', 'Reading, Writing, Listening', 'A wikibooks project-- has introductory lessons w/ audio and more resources (haven''t clicked through them) that might be useful.', false, false, 'tsannifer''s French resources spreadsheet'),
('Beelinguapp', NULL, 'app', 'core_course', 'a1_a2', 'Reading, Listening', '"Freemium" - Stories/articles accompanied by audio tracks, side-by-side EN/FR reading capability, & overall nice UI.', false, false, 'tsannifer''s French resources spreadsheet'),
('Conjuguemos', 'https://conjuguemos.com/', 'website', 'core_course', 'a1_a2', 'Reading, Writing', 'A site with a lot of exercises for grammar and vocab, as well as printables/activities.', false, false, 'tsannifer''s French resources spreadsheet'),
('Extra French', 'https://www.youtube.com/playlist?list=PLHTO4tffa4bAL6jcoq00g--Gbfb8fg52r', 'youtube', 'core_course', 'a1_a2', 'Listening', 'Sitcom-style educational program to teach French to English speakers.', true, false, 'tsannifer''s French resources spreadsheet'),
('Français en Dialogue', 'https://www.youtube.com/channel/UCoejp2Yl88dVi0L3WRYtp2A', 'youtube', 'core_course', 'a1_a2', 'Reading, Listening', 'Videos of recorded conversations with transcripts on the screen.', false, false, 'tsannifer''s French resources spreadsheet'),
('Français interactif: verb practice', 'https://www.laits.utexas.edu/fi/vp/', 'website', 'core_course', 'a1_a2', 'Reading, Writing', 'Exercises to practice verb conjugation. I also recommend the rest of the Français interactif exercises!', false, false, 'tsannifer''s French resources spreadsheet'),
('French Today: Learn French Vocabulary & Pronunciation with Video Game Clips', 'https://www.youtube.com/playlist?list=PLXAfwCr4--2uPMRb5a30tkW-L81_b-u5-', 'youtube', 'core_course', 'a1_a2', 'Listening', 'As a Sims fan myself, I found this to be really cool and helpful.', false, false, 'tsannifer''s French resources spreadsheet'),
('French Your Way', 'https://www.frenchyourway.com.au', 'podcast', 'core_course', 'a1_a2', 'Reading, Writing, Speaking', 'The podcast is mostly in English and is a good learning supplement. Recommended: subjunctive review episodes for A2-B1 learners.', true, false, 'tsannifer''s French resources spreadsheet'),
('Le français par la méthode nature', 'https://ufile.io/xbmls9y2', 'book', 'core_course', 'a1_a2', 'Reading, Writing', 'Credit: /u/StrikingIce; a book that teaches French by only using French', false, false, 'tsannifer''s French resources spreadsheet'),
('Le Petit Nicholas', NULL, 'book', 'core_course', 'a1_a2', 'Reading, Listening', 'Children''s books for easy reading, and you can find episodes of Le Petit Nicholas by searching on YouTube.', false, false, 'tsannifer''s French resources spreadsheet'),
('Listening Comprehension for "Absolute Beginners"', 'https://www.youtube.com/playlist?list=PLtJL6GKh6j0X0fFVBERiwojQ5RnTXNEFL', 'youtube', 'core_course', 'a1_a2', 'Listening', 'It really should be for beginners. :P Very useful, quick listening comprehension exercises by FrenchPod101', true, false, 'tsannifer''s French resources spreadsheet'),
('Mondly ("Learn & Speak French")', NULL, 'app', 'core_course', 'a1_a2', 'Reading, Writing, Listening, Speaking', 'App lets you record yourself speaking scripted convos + learn vocab/grammar', false, false, 'tsannifer''s French resources spreadsheet'),
('Sublexis', 'https://www.sublexis.com', 'website', 'core_course', 'a1_a2', 'Reading, Listening', 'The website has some flashcards of movie stills paired with French subtitles/audio tracks. IG has French "word of the day" type posts.', false, false, 'tsannifer''s French resources spreadsheet'),
('Verbix', 'https://www.verbix.com', 'website', 'core_course', 'a1_a2', 'Reading, Writing', 'Verb conjugation search engine with some word search games available for French', false, false, 'tsannifer''s French resources spreadsheet'),
('Amélioration du français', 'https://www.ccdmd.qc.ca/fr/', 'website', 'core_course', 'a2_b1', 'Reading, Writing', 'Games & activities to exercise knowledge of French (website is entirely in French)', false, false, 'tsannifer''s French resources spreadsheet'),
('À vs De: French Prepositions', 'https://www.thoughtco.com/a-vs-de-french-prepositions-4080520', 'article', 'core_course', 'a2_b1', 'Reading, Writing, Speaking', 'A closer look at these prepositions and when to use them.', false, false, 'tsannifer''s French resources spreadsheet'),
('Français Authentique', 'https://www.youtube.com/channel/UCQpM25U6iqaRSO-SZxd5oDw', 'youtube', 'core_course', 'a2_b1', 'Listening, Speaking', 'Free app available with transcripts. Videos entirely in French but Johan speaks VERY clearly and slowly w/o sounding robotic', true, false, 'tsannifer''s French resources spreadsheet'),
('Fred Grün', 'https://www.youtube.com/channel/UCLfvSY_0TO701lP2_WZJUQw', 'youtube', 'core_course', 'a2_b1', 'Listening, Speaking', 'Helpful videos on spoken, colloquial French and other tips.', false, false, 'tsannifer''s French resources spreadsheet'),
('French Today: Learn French Grammar with Video Game Clips', 'https://www.youtube.com/playlist?list=PLXAfwCr4--2txPWZXQJKd85K4A28Ua9-r', 'youtube', 'core_course', 'a2_b1', 'Listening', 'Narration over Sims 4 gameplay to teach grammar.', true, false, 'tsannifer''s French resources spreadsheet'),
('Lingro', 'http://lingro.com/', 'website', 'core_course', 'a2_b1', 'Reading', 'Tool that lets you click words on a website to get translations and review them later.', false, false, 'tsannifer''s French resources spreadsheet'),
('Listening Comprehension for Beginners', 'https://www.youtube.com/playlist?list=PLtJL6GKh6j0UTjmp04Sy92L_VCdyizdAh', 'youtube', 'core_course', 'a2_b1', 'Listening', 'The next in FrenchPod101''s series for listening comprehension exercises.', true, false, 'tsannifer''s French resources spreadsheet'),
('News in Slow French', 'https://www.newsinslowfrench.com/', 'website', 'core_course', 'a2_b1', 'Listening', 'As the name suggests, news in slowly spoken French, with transcripts.', false, false, 'tsannifer''s French resources spreadsheet'),
('Oh La La, I Speak French!', 'https://www.youtube.com/user/ohlalafrench/featured', 'youtube', 'core_course', 'a2_b1', 'Listening', 'French lessons and dialogues/skits for French learners.', false, false, 'tsannifer''s French resources spreadsheet'),
('Podcast Français Facile', 'http://www.podcastfrancaisfacile.com', 'website', 'core_course', 'a2_b1', 'Listening', 'Hundreds of dialogues with transcripts and listening comprehension quizzes, dictations, etc.', true, false, 'tsannifer''s French resources spreadsheet'),
('RFI: Savoirs', 'https://savoirs.rfi.fr/en', 'website', 'core_course', 'a2_b1', 'Reading, Writing, Listening', 'A news website with a section for those who want to learn & teach French. There are audios, activities, etc. available.', false, false, 'tsannifer''s French resources spreadsheet'),
('Scholingua Conjugation Trainer', 'https://www.scholingua.com/en/fr/conjugation-trainer', 'website', 'core_course', 'a2_b1', 'Reading, Writing', 'Exercises to help conjugate verbs', false, false, 'tsannifer''s French resources spreadsheet'),
('Easy French', 'https://www.youtube.com/playlist?list=PLA5UIoabheFMYWWnGFFxl8_nvVZWZSykc', 'youtube', 'core_course', 'b1_b2', 'Listening', 'French & English subtitles: French locals are interviewed in this series about various topics on daily life & culture', true, false, 'tsannifer''s French resources spreadsheet'),
('French mornings with Elisa', 'https://www.youtube.com/channel/UCbj8Qov-9b5WTU1X4y7Yt-w', 'youtube', 'core_course', 'b1_b2', 'Listening, Speaking', 'Short French lessons and vlogs with French & English subtitles', false, false, 'tsannifer''s French resources spreadsheet'),
('French Voices', 'http://frenchyourway.com.au/category/frenchvoices', 'podcast', 'core_course', 'b1_b2', 'Listening', 'Podcast where Jessica (French Your Way) interviews people entirely in French. Transcripts and listening comprehension exercises available.', true, false, 'tsannifer''s French resources spreadsheet'),
('Home Language', 'https://www.youtube.com/channel/UCFu6uJDqU_6vCIyN9KpMPLg', 'youtube', 'core_course', 'b1_b2', 'Listening, Speaking', 'French teacher''s YouTube channel. She speaks in French, with French subtitles.', false, false, 'tsannifer''s French resources spreadsheet'),
('Learn ALL French Holidays in 80 Minutes', 'https://www.youtube.com/watch?v=IQScQOZx9Rc', 'youtube', 'core_course', 'b1_b2', 'Reading, Listening', 'Video compilation with some little exercises/quizzes along the way. Subtitles in both FR and EN.', false, false, 'tsannifer''s French resources spreadsheet'),
('Listening Comprehension: Intermediate', 'https://www.youtube.com/playlist?list=PLtJL6GKh6j0W1GFbzc5ANZqtidjrLUAGJ', 'youtube', 'core_course', 'b1_b2', 'Listening', 'The next in FrenchPod101''s series for beginner listening comprehension exercises.', true, false, 'tsannifer''s French resources spreadsheet'),
('Lyrics Training', 'https://lyricstraining.com/fr/', 'website', 'core_course', 'b1_b2', 'Listening', 'Popular songs are used in listening comprehension exercises. Listen to parts of the song and fill in blanks.', true, false, 'tsannifer''s French resources spreadsheet'),
('Français de nos régions', 'https://francaisdenosregions.com/', 'website', 'core_course', 'b2_c1', 'Reading, Listening', 'Blog (entirely in French) about the differences in spoken French, regionally in France and globally.', false, false, 'tsannifer''s French resources spreadsheet'),
('French Listening Comprehension: Advanced', 'https://www.youtube.com/watch?v=4DKgSjgMbHE&list=PLtJL6GKh6j0Wr08Vna6v0HuHmYNpsjWWf', 'youtube', 'core_course', 'b2_c1', 'Listening', NULL, true, false, 'tsannifer''s French resources spreadsheet'),
('Listening Comprehension: Advanced', 'https://www.youtube.com/playlist?list=PLtJL6GKh6j0Wr08Vna6v0HuHmYNpsjWWf', 'youtube', 'core_course', 'b2_c1', 'Listening', 'The next in FrenchPod101''s series for listening comprehension exercises.', true, false, 'tsannifer''s French resources spreadsheet'),
('Memrise - Advanced vocabulary', 'https://www.memrise.com/course/885/advanced-vocabulary/', 'app', 'core_course', 'b2_c1', 'Reading, Writing, Listening', '5000+ advanced words and expressions. The audio clips get pretty fast, and they abbreviate "quelque chose" as qqch and "quelqu''un" as qqn', false, false, 'tsannifer''s French resources spreadsheet'),
('/r/French & /r/languagelearning', 'https://www.reddit.com/r/French', 'website', 'extras', NULL, 'Extra Help', 'Many of the resources here were found thanks to the good folks of the French & Language Learning subreddits.', false, false, 'tsannifer''s French resources spreadsheet'),
('250 Conversation Starters', 'https://conversationstartersworld.com/250-conversation-starters/', 'website', 'extras', NULL, 'Extra Help', 'Question suggestions for language exchange - could also use these to practice speaking to yourself.', false, false, 'tsannifer''s French resources spreadsheet'),
('Conversations Questions, Language Exchanges, and the Science of Friendship', 'https://fluent-forever.com/conversation-questions/', 'website', 'extras', NULL, 'Extra Help', 'Question suggestions for language exchange - could also use these to practice speaking to yourself.', false, false, 'tsannifer''s French resources spreadsheet'),
('Expressio.fr', 'http://www.expressio.fr/index.php', 'website', 'extras', NULL, 'Extra Help', 'An expression/idiom search engine. Allows you to view & search for French idioms and their explanations. Entirely in French.', false, false, 'tsannifer''s French resources spreadsheet'),
('Language Exchange - So What Do You Want to Talk About?', 'http://www.tobefluent.com/2014/09/02/language-exchange-so-what-do-you-want-to-talk-about/', 'website', 'extras', NULL, 'Extra Help', 'Question suggestions for language exchange - could also use these to practice speaking to yourself.', false, false, 'tsannifer''s French resources spreadsheet'),
('Let''s Learn French! Grammar: Gender', 'https://www.youtube.com/watch?v=7AoLLBwLfQE', 'website', 'extras', NULL, 'Extra Help', NULL, false, false, 'tsannifer''s French resources spreadsheet'),
('Larousse French Dictionary', 'http://www.larousse.com/en/dictionaries/french', 'website', 'extras', NULL, 'Extra Help', 'They also have a recipes section, if cooking would motivate you further! :)', false, false, 'tsannifer''s French resources spreadsheet'),
('The Challenge of Translating Harry Potter into French', 'http://www.ox.ac.uk/news/arts-blog/challenge-translating-harry-potter-french', 'article', 'extras', NULL, 'Information/For Fun', 'Really interesting article that made me appreciate the French version of the HP books a lot more.', false, false, 'tsannifer''s French resources spreadsheet'),
('Common European Framework of Reference for Languages / CEFR', 'https://en.wikipedia.org/wiki/Common_European_Framework_of_Reference_for_Languages#Common_reference_levels', 'article', 'extras', NULL, 'Information/For Fun', 'Explains the meanings behind each of the proficiency levels (A1, A2, B1, B2, C1, C2)', false, false, 'tsannifer''s French resources spreadsheet'),
('How Long Does It Take to Become Fluent?', 'http://www.languagesurfer.com/2012/08/21/how-long-does-it-take-to-become-fluent/', 'article', 'extras', NULL, 'Information/For Fun', NULL, false, false, 'tsannifer''s French resources spreadsheet'),
('How Long Should it Take to Learn a Language?', 'http://blog.thelinguist.com/how-long-should-it-take-to-learn-a-language', 'article', 'extras', NULL, 'Information/For Fun', NULL, false, false, 'tsannifer''s French resources spreadsheet'),
('French Speaking Countries & Locations', 'http://www.effectivelanguagelearning.com/language-guide/french', 'article', 'extras', NULL, 'Information/For Fun', NULL, false, false, 'tsannifer''s French resources spreadsheet'),
('La langue française: The French Language', 'https://www.youtube.com/watch?v=Tfxf4pV-zJg', 'article', 'extras', NULL, 'Information/For Fun', 'Interesting video about the history of French and some grammar concepts.', false, false, 'tsannifer''s French resources spreadsheet'),
('The Romance Languages and What Makes Them Amazing', 'https://www.youtube.com/watch?v=6o140Ni6yiM', 'article', 'extras', NULL, 'Information/For Fun', 'Cool information video on romance languages (French included)', false, false, 'tsannifer''s French resources spreadsheet'),
('AU QUÉBEC ON NE DIT PAS ... MAIS ON DIT ...!!', 'https://www.youtube.com/watch?v=e2mELjiDgMk', 'website', 'extras', NULL, 'QUÉBÉCOIS HELP', '(Completely in French) a humorous video on some vocabulary differences between France & Quebec', false, false, 'tsannifer''s French resources spreadsheet'),
('QUÉBÉCOIS POUR LES NULS', 'https://www.youtube.com/watch?v=qYm83H5TOMM', 'website', 'extras', NULL, 'QUÉBÉCOIS HELP', '(Completely in French) - video explains the Quebecois accent as well as some expressions unique to Quebec.', false, false, 'tsannifer''s French resources spreadsheet'),
('Are You Stuck in a Language-Learning Plateau - and Not Sure What to Do?', 'http://www.smartlanguagelearner.com/language-learning-plateau/', 'article', 'extras', NULL, 'Tips & Motivation', NULL, false, false, 'tsannifer''s French resources spreadsheet'),
('How to Easily Guess the Gender of French Nouns with 80% Accuracy', 'https://frenchtogether.com/french-nouns-gender/', 'article', 'extras', NULL, 'Tips & Motivation', NULL, false, false, 'tsannifer''s French resources spreadsheet'),
('How to Pronounce the French "R"', 'https://www.youtube.com/watch?v=YCw_lEb1qXk', 'article', 'extras', NULL, 'Tips & Motivation', 'A guide to mastering the French R sound.', false, false, 'tsannifer''s French resources spreadsheet'),
('Language Learning: A How-To', 'https://www.reddit.com/r/languagelearning/comments/5ian7q/language_learning_a_howto/', 'article', 'extras', NULL, 'Tips & Motivation', 'A comprehensive guide on structuring self-study.', false, false, 'tsannifer''s French resources spreadsheet'),
('French Pronunciation: Accents', 'https://polyglotclub.com/wiki/Language/French/Pronunciation/Accents', 'article', 'extras', NULL, 'Tips & Motivation', 'A guide to accent pronunciation in French.', false, false, 'tsannifer''s French resources spreadsheet'),
